content.problemStatement:
You are given a function:
int* ReArrangeArrayElements(int* arr, int length);
int* ReArrangeArrayElements(int* arr, int length);
static int[] ReArrangeArrayElements(int[] arr){}
static int[] ReArrangeArrayElements(int[] arr){}
def ReArrangeArrayElements(arr):
The function accepts an array of integers and its length as input. Implement the function so that it
returns the array after re-arranging it such that even numbers occupy even indices and odd
numbers occupy odd indices.
Note:
1. The relative ordering of even numbers should not change among themselves.
2. The relative ordering of odd numbers should not change among themselves.
3. The re-arrangement is to be done in-place i.e. you cannot use another array.
4. The 0th index of the re-arranged array should contain an even number.
Assumption: You may assume that the array is of even length and half the numbers are even and
half are odd.

code.C:
#include <stdio.h>
#include <stdlib.h>
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int *arr = (int*)malloc(n * sizeof(int));
    int *evens = (int*)malloc(n * sizeof(int)); int e = 0;
    int *odds = (int*)malloc(n * sizeof(int)); int o = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
        if (arr[i] % 2 == 0) evens[e++] = arr[i];
        else odds[o++] = arr[i];
    }
    int first = 1;
    for (int i = 0; i < e && i < o; i++) {
        if (!first) putchar(' ');
        printf("%d %d", evens[i], odds[i]);
        first = 0;
    }
    putchar('\n');
    free(arr); free(evens); free(odds);
    return 0;
}

code.C++:
#include <iostream>
#include <vector>
using namespace std;
int main() {
    int n; if (cin >> n) {
        vector<int> evens, odds;
        for (int i = 0; i < n; i++) {
            int x; cin >> x;
            if (x % 2 == 0) evens.push_back(x);
            else odds.push_back(x);
        }
        for (size_t i = 0; i < evens.size() && i < odds.size(); i++) {
            if (i > 0) cout << " ";
            cout << evens[i] << " " << odds[i];
        }
        cout << "\n";
    }
    return 0;
}

code.Java:
import java.util.Scanner;
import java.util.ArrayList;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            ArrayList<Integer> evens = new ArrayList<>();
            ArrayList<Integer> odds = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                int x = sc.nextInt();
                if (x % 2 == 0) evens.add(x); else odds.add(x);
            }
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < evens.size() && i < odds.size(); i++) {
                if (sb.length() > 0) sb.append(" ");
                sb.append(evens.get(i)).append(" ").append(odds.get(i));
            }
            System.out.println(sb.toString());
        }
    }
}

