const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/).map(Number);
    if (toks.length > 0) {
        const n = toks[0];
        const arr = toks.slice(1, 1 + n);
        const evens = arr.filter(x => x % 2 === 0);
        const odds = arr.filter(x => x % 2 !== 0);
        const res = [];
        for (let i = 0; i < Math.min(evens.length, odds.length); i++) {
            res.push(evens[i], odds[i]);
        }
        console.log(res.join(" "));
    }
}
